module FauFTBWay(
  input         clock,
  input         reset,
  input  [15:0] io_reqTag,
  output        io_resp_valid,
  output [3:0]  io_resp_offset,
  output [1:0]  io_resp_tarStat,
  output [19:0] io_resp_lower,
  output        io_resp_sharing,
  output        io_resp_carry,
  output [3:0]  io_resp_pftAddr,
  output        io_resp_isCall,
  output        io_resp_isRet,
  output        io_resp_isJalr,
  output        io_resp_last_may_be_rvi_call,
  output        io_resp_alwaysTaken,
  output        io_respHit,
  input  [15:0] io_updateReqTag,
  output        io_updateHit,
  input         io_writeValid,
  input         io_writeEntry_valid,
  input  [3:0]  io_writeEntry_offset,
  input  [1:0]  io_writeEntry_tarStat,
  input  [19:0] io_writeEntry_lower,
  input         io_writeEntry_sharing,
  input         io_writeEntry_carry,
  input  [3:0]  io_writeEntry_pftAddr,
  input         io_writeEntry_isCall,
  input         io_writeEntry_isRet,
  input         io_writeEntry_isJalr,
  input         io_writeEntry_last_may_be_rvi_call,
  input         io_writeEntry_alwaysTaken,
  input  [15:0] io_writeTag
);

  reg        valid;
  reg [15:0] tag;
  reg        data_valid;
  reg [3:0]  data_offset;
  reg [1:0]  data_tarStat;
  reg [19:0] data_lower;
  reg        data_sharing;
  reg        data_carry;
  reg [3:0]  data_pftAddr;
  reg        data_isCall;
  reg        data_isRet;
  reg        data_isJalr;
  reg        data_last_may_be_rvi_call;
  reg        data_alwaysTaken;
  always @(posedge clock) begin
    if (reset)
      valid <= 1'h0;
    else
      valid <= io_writeValid | valid;
    if (io_writeValid) begin
      tag <= io_writeTag;
      data_valid <= io_writeEntry_valid;
      data_offset <= io_writeEntry_offset;
      data_tarStat <= io_writeEntry_tarStat;
      data_lower <= io_writeEntry_lower;
      data_sharing <= io_writeEntry_sharing;
      data_carry <= io_writeEntry_carry;
      data_pftAddr <= io_writeEntry_pftAddr;
      data_isCall <= io_writeEntry_isCall;
      data_isRet <= io_writeEntry_isRet;
      data_isJalr <= io_writeEntry_isJalr;
      data_last_may_be_rvi_call <= io_writeEntry_last_may_be_rvi_call;
      data_alwaysTaken <= io_writeEntry_alwaysTaken;
    end
  end // always @(posedge)
  assign io_resp_valid = data_valid;
  assign io_resp_offset = data_offset;
  assign io_resp_tarStat = data_tarStat;
  assign io_resp_lower = data_lower;
  assign io_resp_sharing = data_sharing;
  assign io_resp_carry = data_carry;
  assign io_resp_pftAddr = data_pftAddr;
  assign io_resp_isCall = data_isCall;
  assign io_resp_isRet = data_isRet;
  assign io_resp_isJalr = data_isJalr;
  assign io_resp_last_may_be_rvi_call = data_last_may_be_rvi_call;
  assign io_resp_alwaysTaken = data_alwaysTaken;
  assign io_respHit = tag == io_reqTag & valid;
  assign io_updateHit = tag == io_updateReqTag & valid | io_writeTag == io_updateReqTag & io_writeValid;
endmodule

