    & _array_io_r_resp_data_2 | holdRidx == 4'h3 & _array_io_r_resp_data_3 | holdRidx == 4'h4 & _array_io_r_resp_data_4
    | holdRidx == 4'h5 & _array_io_r_resp_data_5 | holdRidx == 4'h6 & _array_io_r_resp_data_6 | holdRidx == 4'h7
    & _array_io_r_resp_data_7 | holdRidx == 4'h8 & _array_io_r_resp_data_8 | holdRidx == 4'h9 & _array_io_r_resp_data_9
    | holdRidx == 4'hA & _array_io_r_resp_data_10 | holdRidx == 4'hB & _array_io_r_resp_data_11 | holdRidx == 4'hC
    & _array_io_r_resp_data_12 | holdRidx == 4'hD & _array_io_r_resp_data_13 | holdRidx == 4'hE
    & _array_io_r_resp_data_14 | (&holdRidx) & _array_io_r_resp_data_15;
