// VCS coverage exclude_file
module array_256x12(
  input  [7:0]  RW0_addr,
  input         RW0_en,
  input         RW0_clk,
  input         RW0_wmode,
  input  [11:0] RW0_wdata,
  output [11:0] RW0_rdata
);

  reg [11:0] Memory[0:255];
  reg [7:0]  _RW0_raddr_d0;
  reg        _RW0_ren_d0;
  reg        _RW0_rmode_d0;
  always @(posedge RW0_clk) begin
    _RW0_raddr_d0 <= RW0_addr;
    _RW0_ren_d0 <= RW0_en;
    _RW0_rmode_d0 <= RW0_wmode;
    if (RW0_en & RW0_wmode & 1'h1)
      Memory[RW0_addr] <= RW0_wdata;
  end // always @(posedge)
  assign RW0_rdata = _RW0_ren_d0 & ~_RW0_rmode_d0 ? Memory[_RW0_raddr_d0] : 12'bx;
endmodule

module sram_array_1p256x24m12_bist(
  input         mbist_selectedOH,
  input         mbist_dft_ram_bypass,
  input         mbist_dft_ram_bp_clken,
  input  [19:0] rf2p_ctrl,
  input  [12:0] rmsp_hd_ctrl,
  input  [16:0] rmsp_hs_ctrl,
  input         RW0_clk,
  input  [7:0]  RW0_addr,
  input         RW0_en,
  input         RW0_wmode,
  input  [1:0]  RW0_wmask,
  input  [23:0] RW0_wdata,
  output [23:0] RW0_rdata
);

  wire        array_RW0_rdata_MPORT_wmode;
  wire        _RW0_rdata_T_3;
  wire        _RW0_rdata_T_2;
  wire        _array_1_ext_RW0_wmode;
  wire [11:0] _array_1_ext_RW0_wdata;
  wire [11:0] _array_1_ext_RW0_rdata;
  wire        _array_0_ext_RW0_wmode;
  wire [11:0] _array_0_ext_RW0_wdata;
  wire [11:0] _array_0_ext_RW0_rdata;
  assign _RW0_rdata_T_2 = RW0_wmask[0];
  assign _RW0_rdata_T_3 = RW0_wmask[1];
  assign array_RW0_rdata_MPORT_wmode = RW0_en & RW0_wmode & (|RW0_wmask);
  assign _array_0_ext_RW0_wmode = array_RW0_rdata_MPORT_wmode & RW0_wmode & _RW0_rdata_T_2;
  assign _array_0_ext_RW0_wdata = RW0_wdata[11:0];
  array_256x12 array_0_ext (
    .RW0_addr  (RW0_addr),
    .RW0_en    (RW0_en),
    .RW0_clk   (RW0_clk),
    .RW0_wmode (_array_0_ext_RW0_wmode),
    .RW0_wdata (_array_0_ext_RW0_wdata),
    .RW0_rdata (_array_0_ext_RW0_rdata)
  );
  assign _array_1_ext_RW0_wmode = array_RW0_rdata_MPORT_wmode & RW0_wmode & _RW0_rdata_T_3;
  assign _array_1_ext_RW0_wdata = RW0_wdata[23:12];
  array_256x12 array_1_ext (
    .RW0_addr  (RW0_addr),
    .RW0_en    (RW0_en),
    .RW0_clk   (RW0_clk),
    .RW0_wmode (_array_1_ext_RW0_wmode),
    .RW0_wdata (_array_1_ext_RW0_wdata),
    .RW0_rdata (_array_1_ext_RW0_rdata)
  );
  assign RW0_rdata = {_array_1_ext_RW0_rdata, _array_0_ext_RW0_rdata};
endmodule

module SRAMTemplate_12(
  input        clock,
  input        reset,
  output       io_r_req_ready,
  input        io_r_req_valid,
  input  [7:0] io_r_req_bits_setIdx,
  output       io_r_resp_data_0_valid,
  output [7:0] io_r_resp_data_0_tag,
  output [2:0] io_r_resp_data_0_ctr,
  output       io_r_resp_data_1_valid,
  output [7:0] io_r_resp_data_1_tag,
  output [2:0] io_r_resp_data_1_ctr,
  input        io_w_req_valid,
  input  [7:0] io_w_req_bits_setIdx,
  input  [7:0] io_w_req_bits_data_0_tag,
  input  [2:0] io_w_req_bits_data_0_ctr,
  input  [7:0] io_w_req_bits_data_1_tag,
  input  [2:0] io_w_req_bits_data_1_ctr,
  input  [1:0] io_w_req_bits_waymask
);

  wire        _array_mbist_selectedOH;
  wire        _array_RW0_en;
  wire [23:0] _array_RW0_wdata;
  wire [23:0] _array_RW0_rdata;
  wire        broadCastSignals_ram_hold = 1'h0;
  wire        broadCastSignals_ram_bypass = 1'h0;
  wire        broadCastSignals_ram_bp_clken = 1'h0;
  wire        broadCastSignals_l3dataram_clk = 1'h0;
  wire        broadCastSignals_l3dataramclk_bypass = 1'h0;
  wire        broadCastSignals_cgen = 1'h0;
  wire [16:0] broadCastSignals_rmsp_hs_ctrl = 17'h0;
  wire [12:0] broadCastSignals_rmsp_hd_ctrl = 13'h0;
  wire [19:0] broadCastSignals_rf2p_ctrl = 20'h0;
  reg         _resetState;
  reg  [7:0]  _resetSet;
  wire        wen = io_w_req_valid | _resetState & ~reset;
  wire [7:0]  setIdx = _resetState ? _resetSet : io_w_req_bits_setIdx;
  wire [7:0]  _wdata_T_0_tag = _resetState ? 8'h0 : io_w_req_bits_data_0_tag;
  wire [2:0]  _wdata_T_0_ctr = _resetState ? 3'h0 : io_w_req_bits_data_0_ctr;
  wire [7:0]  _wdata_T_1_tag = _resetState ? 8'h0 : io_w_req_bits_data_1_tag;
  wire [2:0]  _wdata_T_1_ctr = _resetState ? 3'h0 : io_w_req_bits_data_1_ctr;
  wire [1:0]  waymask = _resetState ? 2'h3 : io_w_req_bits_waymask;
  wire        toSRAMRen = io_r_req_valid & ~wen;
  wire [7:0]  _GEN = wen ? setIdx : io_r_req_bits_setIdx;
  reg         rdata_REG;
  reg  [11:0] rdata_hold_data_0;
  reg  [11:0] rdata_hold_data_1;
  wire [11:0] rdata_0 = rdata_REG ? _array_RW0_rdata[11:0] : rdata_hold_data_0;
  wire [11:0] rdata_1 = rdata_REG ? _array_RW0_rdata[23:12] : rdata_hold_data_1;
  always @(posedge clock) begin
    if (reset) begin
      _resetState <= 1'h1;
      _resetSet <= 8'h0;
    end
    else begin
      _resetState <= ~(_resetState & (&_resetSet)) & _resetState;
      if (_resetState)
        _resetSet <= 8'(_resetSet + 8'h1);
    end
    rdata_REG <= toSRAMRen;
    if (rdata_REG) begin
      rdata_hold_data_0 <= _array_RW0_rdata[11:0];
      rdata_hold_data_1 <= _array_RW0_rdata[23:12];
    end
  end // always @(posedge)
  assign _array_mbist_selectedOH = ~broadCastSignals_ram_hold;
  assign _array_RW0_en = wen | toSRAMRen;
  assign _array_RW0_wdata =
    {~_resetState, _wdata_T_1_tag, _wdata_T_1_ctr, ~_resetState, _wdata_T_0_tag, _wdata_T_0_ctr};
  sram_array_1p256x24m12_bist array (
    .mbist_selectedOH       (_array_mbist_selectedOH),
    .mbist_dft_ram_bypass   (broadCastSignals_ram_bypass),
    .mbist_dft_ram_bp_clken (broadCastSignals_ram_bp_clken),
    .rf2p_ctrl              (broadCastSignals_rf2p_ctrl),
    .rmsp_hd_ctrl           (broadCastSignals_rmsp_hd_ctrl),
    .rmsp_hs_ctrl           (broadCastSignals_rmsp_hs_ctrl),
    .RW0_clk                (clock),
    .RW0_addr               (_GEN),
    .RW0_en                 (_array_RW0_en),
    .RW0_wmode              (wen),
    .RW0_wmask              (waymask),
    .RW0_wdata              (_array_RW0_wdata),
    .RW0_rdata              (_array_RW0_rdata)
  );
  assign io_r_req_ready = ~_resetState & ~wen;
  assign io_r_resp_data_0_valid = rdata_0[11];
  assign io_r_resp_data_0_tag = rdata_0[10:3];
  assign io_r_resp_data_0_ctr = rdata_0[2:0];
  assign io_r_resp_data_1_valid = rdata_1[11];
  assign io_r_resp_data_1_tag = rdata_1[10:3];
  assign io_r_resp_data_1_ctr = rdata_1[2:0];
endmodule

module FoldedSRAMTemplate_1(
  input        clock,
  input        reset,
  output       io_r_req_ready,
  input        io_r_req_valid,
  input  [8:0] io_r_req_bits_setIdx,
  output       io_r_resp_data_0_valid,
  output [7:0] io_r_resp_data_0_tag,
  output [2:0] io_r_resp_data_0_ctr,
  input        io_w_req_valid,
  input  [8:0] io_w_req_bits_setIdx,
  input  [7:0] io_w_req_bits_data_0_tag,
  input  [2:0] io_w_req_bits_data_0_ctr
);

  wire [7:0] _array_io_r_req_bits_setIdx;
  wire [7:0] _array_io_w_req_bits_setIdx;
  wire [1:0] _array_io_w_req_bits_waymask;
  wire       _array_io_r_resp_data_0_valid;
  wire [7:0] _array_io_r_resp_data_0_tag;
  wire [2:0] _array_io_r_resp_data_0_ctr;
  wire       _array_io_r_resp_data_1_valid;
  wire [7:0] _array_io_r_resp_data_1_tag;
  wire [2:0] _array_io_r_resp_data_1_ctr;
  reg        ridx;
  reg        holdRidx_REG;
  reg        holdRidx_hold_data;
  wire       holdRidx = holdRidx_REG ? ridx : holdRidx_hold_data;
  wire [2:0] _io_r_resp_data_0_T_4 = holdRidx ? 3'h0 : _array_io_r_resp_data_0_ctr;
  wire [2:0] _io_r_resp_data_0_T_5 = holdRidx ? _array_io_r_resp_data_1_ctr : 3'h0;
  wire [7:0] _io_r_resp_data_0_T_7 = holdRidx ? 8'h0 : _array_io_r_resp_data_0_tag;
  wire [7:0] _io_r_resp_data_0_T_8 = holdRidx ? _array_io_r_resp_data_1_tag : 8'h0;
  always @(posedge clock) begin
    ridx <= io_r_req_bits_setIdx[0];
    holdRidx_REG <= io_r_req_valid;
    if (holdRidx_REG)
      holdRidx_hold_data <= ridx;
  end // always @(posedge)
  assign _array_io_r_req_bits_setIdx = io_r_req_bits_setIdx[8:1];
  assign _array_io_w_req_bits_setIdx = io_w_req_bits_setIdx[8:1];
  assign _array_io_w_req_bits_waymask = 2'h1 << io_w_req_bits_setIdx[0];
  SRAMTemplate_12 array (
    .clock                    (clock),
    .reset                    (reset),
    .io_r_req_ready           (io_r_req_ready),
    .io_r_req_valid           (io_r_req_valid),
    .io_r_req_bits_setIdx     (_array_io_r_req_bits_setIdx),
    .io_r_resp_data_0_valid   (_array_io_r_resp_data_0_valid),
    .io_r_resp_data_0_tag     (_array_io_r_resp_data_0_tag),
    .io_r_resp_data_0_ctr     (_array_io_r_resp_data_0_ctr),
    .io_r_resp_data_1_valid   (_array_io_r_resp_data_1_valid),
    .io_r_resp_data_1_tag     (_array_io_r_resp_data_1_tag),
    .io_r_resp_data_1_ctr     (_array_io_r_resp_data_1_ctr),
    .io_w_req_valid           (io_w_req_valid),
    .io_w_req_bits_setIdx     (_array_io_w_req_bits_setIdx),
    .io_w_req_bits_data_0_tag (io_w_req_bits_data_0_tag),
    .io_w_req_bits_data_0_ctr (io_w_req_bits_data_0_ctr),
    .io_w_req_bits_data_1_tag (io_w_req_bits_data_0_tag),
    .io_w_req_bits_data_1_ctr (io_w_req_bits_data_0_ctr),
    .io_w_req_bits_waymask    (_array_io_w_req_bits_waymask)
  );
  assign io_r_resp_data_0_valid = ~holdRidx & _array_io_r_resp_data_0_valid | holdRidx & _array_io_r_resp_data_1_valid;
  assign io_r_resp_data_0_tag = _io_r_resp_data_0_T_7 | _io_r_resp_data_0_T_8;
  assign io_r_resp_data_0_ctr = _io_r_resp_data_0_T_4 | _io_r_resp_data_0_T_5;
endmodule

module CAMTemplate(
  input        clock,
  input        io_r_req_0_idx,
  input  [7:0] io_r_req_0_tag,
  output       io_r_resp_0_0,
  output       io_r_resp_0_1,
  output       io_r_resp_0_2,
  output       io_r_resp_0_3,
  output       io_r_resp_0_4,
  output       io_r_resp_0_5,
  output       io_r_resp_0_6,
  output       io_r_resp_0_7,
  input        io_w_valid,
  input        io_w_bits_data_idx,
  input  [7:0] io_w_bits_data_tag,
  input  [2:0] io_w_bits_index
);

  reg  [8:0] array_0;
  reg  [8:0] array_1;
  reg  [8:0] array_2;
  reg  [8:0] array_3;
  reg  [8:0] array_4;
  reg  [8:0] array_5;
  reg  [8:0] array_6;
  reg  [8:0] array_7;
  wire [8:0] _GEN = {io_r_req_0_idx, io_r_req_0_tag};
  wire [8:0] _array_T = {io_w_bits_data_idx, io_w_bits_data_tag};
  always @(posedge clock) begin
    if (io_w_valid & io_w_bits_index == 3'h0)
      array_0 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h1)
      array_1 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h2)
      array_2 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h3)
      array_3 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h4)
      array_4 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h5)
      array_5 <= _array_T;
    if (io_w_valid & io_w_bits_index == 3'h6)
      array_6 <= _array_T;
    if (io_w_valid & (&io_w_bits_index))
      array_7 <= _array_T;
