  wire        _idxTagCam_io_r_resp_0_3;
  wire        _logHelper_clean;
  wire        _logHelper_dump;
  wire        _logHelper_logEnable;
  wire [63:0] _logHelper_timer;
  reg         everWritten_0;
  reg         everWritten_1;
  reg         everWritten_2;
  reg         everWritten_3;
  wire        hitsOH_1 = _idxTagCam_io_r_resp_0_1 & everWritten_1;
  wire        hitsOH_2 = _idxTagCam_io_r_resp_0_2 & everWritten_2;
  wire        hitsOH_3 = _idxTagCam_io_r_resp_0_3 & everWritten_3;
  wire [1:0]  hitIdx = {|{hitsOH_3, hitsOH_2}, hitsOH_3 | hitsOH_1};
  wire        isHit = _idxTagCam_io_r_resp_0_0 & everWritten_0 | hitsOH_1 | hitsOH_2 | hitsOH_3;
  reg         enqPtr_flag;
  reg  [1:0]  enqPtr_value;
  wire        camWriteEna = io_wen & ~isHit;
  wire [1:0]  writeDataMemIdx = isHit ? hitIdx : enqPtr_value;
  reg  [63:0] counter;
  wire [63:0] _next_counter_T = 64'(counter + {63'h0, io_wen & isHit});
  reg  [63:0] counter_1;
  wire [63:0] _next_counter_T_1 = 64'(counter_1 + {63'h0, io_wen & ~isHit});
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if ((`PRINTF_COND_) & _logHelper_dump & _logHelper_logEnable & ~reset) begin
        $fwrite(32'h80000002, "[PERF ][time=%d] _LOG_MODULE_PATH_: wrbypass_hit, %d\n", _logHelper_timer,
                _next_counter_T);
        $fwrite(32'h80000002, "[PERF ][time=%d] _LOG_MODULE_PATH_: wrbypass_miss, %d\n", _logHelper_timer,
                _next_counter_T_1);
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire [2:0]  _enqPtr_new_ptr_T_1 = 3'({enqPtr_flag, enqPtr_value} + {2'h0, camWriteEna});
  always @(posedge clock) begin
    if (reset) begin
      everWritten_0 <= 1'h0;
      everWritten_1 <= 1'h0;
      everWritten_2 <= 1'h0;
      everWritten_3 <= 1'h0;
      enqPtr_flag <= 1'h0;
      enqPtr_value <= 2'h0;
      counter <= 64'h0;
      counter_1 <= 64'h0;
    end
    else begin
      everWritten_0 <= io_wen & ~isHit & enqPtr_value == 2'h0 | everWritten_0;
      everWritten_1 <= io_wen & ~isHit & enqPtr_value == 2'h1 | everWritten_1;
      everWritten_2 <= io_wen & ~isHit & enqPtr_value == 2'h2 | everWritten_2;
      everWritten_3 <= io_wen & ~isHit & (&enqPtr_value) | everWritten_3;
      enqPtr_flag <= _enqPtr_new_ptr_T_1[2];
      enqPtr_value <= _enqPtr_new_ptr_T_1[1:0];
      if (_logHelper_clean) begin
        counter <= 64'h0;
        counter_1 <= 64'h0;
      end
      else begin
        counter <= _next_counter_T;
        counter_1 <= _next_counter_T_1;
      end
    end
  end // always @(posedge)
  LogHelper logHelper (
    .clean     (_logHelper_clean),
    .dump      (_logHelper_dump),
    .logEnable (_logHelper_logEnable),
    .timer     (_logHelper_timer)
  );
  CAMTemplate_37 idxTagCam (
    .clock              (clock),
    .io_r_req_0_idx     (io_writeIdx),
    .io_r_req_0_tag     (io_writeTag),
    .io_r_resp_0_0      (_idxTagCam_io_r_resp_0_0),
    .io_r_resp_0_1      (_idxTagCam_io_r_resp_0_1),
    .io_r_resp_0_2      (_idxTagCam_io_r_resp_0_2),
    .io_r_resp_0_3      (_idxTagCam_io_r_resp_0_3),
