module sram_array_1p128x70m35_bist(
  input         mbist_selectedOH,
  input         mbist_dft_ram_bypass,
  input         mbist_dft_ram_bp_clken,
  input  [19:0] rf2p_ctrl,
  input  [12:0] rmsp_hd_ctrl,
  input  [16:0] rmsp_hs_ctrl,
  input         RW0_clk,
  input  [6:0]  RW0_addr,
  input         RW0_en,
  input         RW0_wmode,
  input  [1:0]  RW0_wmask,
  input  [69:0] RW0_wdata,
  output [69:0] RW0_rdata
);

  wire        array_RW0_rdata_MPORT_wmode;
  wire        _RW0_rdata_T_3;
  wire        _RW0_rdata_T_2;
  wire        _array_1_ext_RW0_wmode;
  wire [34:0] _array_1_ext_RW0_wdata;
  wire [34:0] _array_1_ext_RW0_rdata;
  wire        _array_0_ext_RW0_wmode;
  wire [34:0] _array_0_ext_RW0_wdata;
  wire [34:0] _array_0_ext_RW0_rdata;
  assign _RW0_rdata_T_2 = RW0_wmask[0];
  assign _RW0_rdata_T_3 = RW0_wmask[1];
  assign array_RW0_rdata_MPORT_wmode = RW0_en & RW0_wmode & (|RW0_wmask);
  assign _array_0_ext_RW0_wmode = array_RW0_rdata_MPORT_wmode & RW0_wmode & _RW0_rdata_T_2;
  assign _array_0_ext_RW0_wdata = RW0_wdata[34:0];
  array_128x35 array_0_ext (
    .RW0_addr  (RW0_addr),
    .RW0_en    (RW0_en),
    .RW0_clk   (RW0_clk),
    .RW0_wmode (_array_0_ext_RW0_wmode),
    .RW0_wdata (_array_0_ext_RW0_wdata),
    .RW0_rdata (_array_0_ext_RW0_rdata)
  );
  assign _array_1_ext_RW0_wmode = array_RW0_rdata_MPORT_wmode & RW0_wmode & _RW0_rdata_T_3;
  assign _array_1_ext_RW0_wdata = RW0_wdata[69:35];
  array_128x35 array_1_ext (
    .RW0_addr  (RW0_addr),
    .RW0_en    (RW0_en),
    .RW0_clk   (RW0_clk),
    .RW0_wmode (_array_1_ext_RW0_wmode),
    .RW0_wdata (_array_1_ext_RW0_wdata),
    .RW0_rdata (_array_1_ext_RW0_rdata)
  );
  assign RW0_rdata = {_array_1_ext_RW0_rdata, _array_0_ext_RW0_rdata};
endmodule

module SRAMTemplate_56(
  input         clock,
  input         reset,
  input         io_r_req_valid,
  input  [6:0]  io_r_req_bits_setIdx,
  output [8:0]  io_r_resp_data_0_tag,
  output [1:0]  io_r_resp_data_0_ctr,
  output [23:0] io_r_resp_data_0_targetLowerBits,
  output [8:0]  io_r_resp_data_1_tag,
  output [1:0]  io_r_resp_data_1_ctr,
  output [23:0] io_r_resp_data_1_targetLowerBits,
  input         io_w_req_valid,
  input  [6:0]  io_w_req_bits_setIdx,
  input  [8:0]  io_w_req_bits_data_0_tag,
  input  [1:0]  io_w_req_bits_data_0_ctr,
  input  [23:0] io_w_req_bits_data_0_targetLowerBits,
  input  [8:0]  io_w_req_bits_data_1_tag,
  input  [1:0]  io_w_req_bits_data_1_ctr,
  input  [23:0] io_w_req_bits_data_1_targetLowerBits,
  input  [1:0]  io_w_req_bits_waymask
);

  wire        _array_mbist_selectedOH;
  wire        _array_RW0_en;
  wire [69:0] _array_RW0_wdata;
  wire [69:0] _array_RW0_rdata;
  wire        broadCastSignals_ram_hold = 1'h0;
  wire        broadCastSignals_ram_bypass = 1'h0;
  wire        broadCastSignals_ram_bp_clken = 1'h0;
  wire        broadCastSignals_l3dataram_clk = 1'h0;
  wire        broadCastSignals_l3dataramclk_bypass = 1'h0;
  wire        broadCastSignals_cgen = 1'h0;
  wire [16:0] broadCastSignals_rmsp_hs_ctrl = 17'h0;
  wire [12:0] broadCastSignals_rmsp_hd_ctrl = 13'h0;
  wire [19:0] broadCastSignals_rf2p_ctrl = 20'h0;
  reg         _resetState;
  reg  [6:0]  _resetSet;
  wire        wen = io_w_req_valid | _resetState & ~reset;
  wire [6:0]  setIdx = _resetState ? _resetSet : io_w_req_bits_setIdx;
  wire [8:0]  _wdata_T_0_tag = _resetState ? 9'h0 : io_w_req_bits_data_0_tag;
  wire [1:0]  _wdata_T_0_ctr = _resetState ? 2'h0 : io_w_req_bits_data_0_ctr;
  wire [23:0] _wdata_T_0_targetLowerBits = _resetState ? 24'h0 : io_w_req_bits_data_0_targetLowerBits;
  wire [8:0]  _wdata_T_1_tag = _resetState ? 9'h0 : io_w_req_bits_data_1_tag;
  wire [1:0]  _wdata_T_1_ctr = _resetState ? 2'h0 : io_w_req_bits_data_1_ctr;
  wire [23:0] _wdata_T_1_targetLowerBits = _resetState ? 24'h0 : io_w_req_bits_data_1_targetLowerBits;
  wire [1:0]  waymask = _resetState ? 2'h3 : io_w_req_bits_waymask;
  wire        toSRAMRen = io_r_req_valid & ~wen;
  wire [6:0]  _GEN = wen ? setIdx : io_r_req_bits_setIdx;
  reg         rdata_REG;
  reg  [34:0] rdata_hold_data_0;
  reg  [34:0] rdata_hold_data_1;
  wire [34:0] rdata_0 = rdata_REG ? _array_RW0_rdata[34:0] : rdata_hold_data_0;
  wire [34:0] rdata_1 = rdata_REG ? _array_RW0_rdata[69:35] : rdata_hold_data_1;
  always @(posedge clock) begin
    if (reset) begin
      _resetState <= 1'h1;
      _resetSet <= 7'h0;
    end
    else begin
      _resetState <= ~(_resetState & (&_resetSet)) & _resetState;
      if (_resetState)
        _resetSet <= 7'(_resetSet + 7'h1);
    end
    rdata_REG <= toSRAMRen;
    if (rdata_REG) begin
      rdata_hold_data_0 <= _array_RW0_rdata[34:0];
      rdata_hold_data_1 <= _array_RW0_rdata[69:35];
    end
  end // always @(posedge)
  assign _array_mbist_selectedOH = ~broadCastSignals_ram_hold;
  assign _array_RW0_en = wen | toSRAMRen;
  assign _array_RW0_wdata =
    {_wdata_T_1_tag,
     _wdata_T_1_ctr,
     _wdata_T_1_targetLowerBits,
     _wdata_T_0_tag,
     _wdata_T_0_ctr,
     _wdata_T_0_targetLowerBits};
  sram_array_1p128x70m35_bist array (
    .mbist_selectedOH       (_array_mbist_selectedOH),
    .mbist_dft_ram_bypass   (broadCastSignals_ram_bypass),
    .mbist_dft_ram_bp_clken (broadCastSignals_ram_bp_clken),
    .rf2p_ctrl              (broadCastSignals_rf2p_ctrl),
    .rmsp_hd_ctrl           (broadCastSignals_rmsp_hd_ctrl),
    .rmsp_hs_ctrl           (broadCastSignals_rmsp_hs_ctrl),
    .RW0_clk                (clock),
    .RW0_addr               (_GEN),
    .RW0_en                 (_array_RW0_en),
    .RW0_wmode              (wen),
    .RW0_wmask              (waymask),
    .RW0_wdata              (_array_RW0_wdata),
    .RW0_rdata              (_array_RW0_rdata)
  );
  assign io_r_resp_data_0_tag = rdata_0[34:26];
  assign io_r_resp_data_0_ctr = rdata_0[25:24];
  assign io_r_resp_data_0_targetLowerBits = rdata_0[23:0];
  assign io_r_resp_data_1_tag = rdata_1[34:26];
  assign io_r_resp_data_1_ctr = rdata_1[25:24];
  assign io_r_resp_data_1_targetLowerBits = rdata_1[23:0];
endmodule

