module DifftestMem1P(
  input         clock,
  input         reset,
  input         read_valid,
  input  [63:0] read_index,
  output [63:0] read_data_0,
  output [63:0] read_data_1,
  output [63:0] read_data_2,
  output [63:0] read_data_3,
  input         write_valid,
  input  [63:0] write_index,
  input  [63:0] write_data_0,
  input  [63:0] write_data_1,
  input  [63:0] write_data_2,
  input  [63:0] write_data_3,
  input  [63:0] write_mask_0,
  input  [63:0] write_mask_1,
  input  [63:0] write_mask_2,
  input  [63:0] write_mask_3
);

  wire [63:0] _helper_3_r_index;
  wire [63:0] _helper_3_w_index;
  wire        _helper_3_enable;
  wire [63:0] _helper_2_r_index;
  wire [63:0] _helper_2_w_index;
  wire        _helper_2_enable;
  wire [63:0] _helper_1_r_index;
  wire [63:0] _helper_1_w_index;
  wire        _helper_1_enable;
  wire        _helper_0_enable;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if (~reset & ~(~read_valid | ~write_valid)) begin
        if (`ASSERT_VERBOSE_COND_)
          $error("Assertion failed: read and write come at the same cycle\n    at Mem.scala:265 assert(!read.valid || !write.valid, \"read and write come at the same cycle\")\n");
        if (`STOP_COND_)
          $fatal;
      end
    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire [63:0] _GEN = {write_index[61:0], 2'h0};
  wire [63:0] _GEN_0 = {read_index[61:0], 2'h0};
  assign _helper_0_enable = ~reset;
  MemRWHelper helper_0 (
    .r_enable (read_valid),
    .r_index  (_GEN_0),
    .r_data   (read_data_0),
    .w_enable (write_valid),
    .w_index  (_GEN),
    .w_data   (write_data_0),
    .w_mask   (write_mask_0),
    .clock    (clock),
    .enable   (_helper_0_enable)
  );
  assign _helper_1_r_index = 64'(_GEN_0 + 64'h1);
  assign _helper_1_w_index = 64'(_GEN + 64'h1);
  assign _helper_1_enable = ~reset;
  MemRWHelper helper_1 (
    .r_enable (read_valid),
    .r_index  (_helper_1_r_index),
    .r_data   (read_data_1),
    .w_enable (write_valid),
    .w_index  (_helper_1_w_index),
    .w_data   (write_data_1),
    .w_mask   (write_mask_1),
    .clock    (clock),
    .enable   (_helper_1_enable)
  );
  assign _helper_2_r_index = 64'(_GEN_0 + 64'h2);
  assign _helper_2_w_index = 64'(_GEN + 64'h2);
  assign _helper_2_enable = ~reset;
  MemRWHelper helper_2 (
    .r_enable (read_valid),
    .r_index  (_helper_2_r_index),
    .r_data   (read_data_2),
    .w_enable (write_valid),
    .w_index  (_helper_2_w_index),
    .w_data   (write_data_2),
    .w_mask   (write_mask_2),
    .clock    (clock),
    .enable   (_helper_2_enable)
  );
  assign _helper_3_r_index = 64'(_GEN_0 + 64'h3);
  assign _helper_3_w_index = 64'(_GEN + 64'h3);
  assign _helper_3_enable = ~reset;
  MemRWHelper helper_3 (
    .r_enable (read_valid),
    .r_index  (_helper_3_r_index),
    .r_data   (read_data_3),
    .w_enable (write_valid),
    .w_index  (_helper_3_w_index),
    .w_data   (write_data_3),
    .w_mask   (write_mask_3),
    .clock    (clock),
    .enable   (_helper_3_enable)
  );
endmodule

